import { Injectable } from '@angular/core';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

@Injectable({
  providedIn: 'root'
})
export class PdfGeneratorService {

  constructor() { }

  imprimirTicket(venta: any, carrito: any[]) {
    // 1. Configuración del documento (A4 vertical, milímetros)
    const doc = new jsPDF('p', 'mm', 'a4');

    const imgData = 'data:image/png;base64,';
     const imgData2 = 'data:image/png;base64,';
    // --- CABECERA ---
    //doc.addImage(imgData2, 'PNG', 15, 10, 30, 15);
    doc.addImage(imgData2, 'PNG', 15, 10, 60, 30);
   

    // Datos de la Empresa (Alineados a la derecha)
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    doc.text("FARMACIA KO2", 195, 20, { align: 'right' });
    
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text("C/ Ejemplo, 123 - Ciudad", 195, 26, { align: 'right' });
    doc.text("CIF: B-12345678", 195, 31, { align: 'right' });
    doc.text("Tel: 900 000 000", 195, 36, { align: 'right' });

    // --- DATOS DEL TICKET ---
    doc.setDrawColor(200, 200, 200);
    doc.line(15, 50, 195, 50); // <--- CAMBIA ESTE 45 POR 50 o 55. Para que quede bien separado

    doc.setFontSize(11);
    doc.text(`Fecha: ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString()}`, 15, 60); // Antes 55
    const idTicket = venta.id || Math.floor(Math.random() * 10000); 
    doc.text(`Ticket Nº: ${idTicket}`, 195, 60, { align: 'right' }); // Antes 55
    doc.text(`Cliente DNI: ${venta.dnicliente || 'Genérico'}`, 15, 67); // Antes 62

    // --- TABLA DE PRODUCTOS ---
    // Preparamos los datos para la tabla
    const bodyData = carrito.map(item => [
      item.cantidadCompra,
      item.articulo.nombre, // O nameproducto según tu modelo
      `${item.articulo.precio.toFixed(2)}€`,
      `${(item.articulo.precio * item.cantidadCompra).toFixed(2)}€`
    ]);

    autoTable(doc, {
      startY: 75,
      head: [['Cant.', 'Producto', 'Precio Unit.', 'Total']],
      body: bodyData,
      theme: 'striped',
      headStyles: { fillColor: [52, 58, 64], textColor: 255 }, // Color oscuro tipo Bootstrap
      styles: { fontSize: 10, cellPadding: 3 },
      columnStyles: {
        0: { halign: 'center', cellWidth: 20 },
        2: { halign: 'right' },
        3: { halign: 'right', fontStyle: 'bold' }
      }
    });

    // --- TOTALES ---
    // Calculamos la posición final de la tabla para poner el total debajo
    const finalY = (doc as any).lastAutoTable.finalY + 10;

    // Calcular total general
    const totalGeneral = carrito.reduce((acc, item) => acc + (item.articulo.precio * item.cantidadCompra), 0);

    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text(`TOTAL A PAGAR: ${totalGeneral.toFixed(2)}€`, 195, finalY, { align: 'right' });

    // --- PIE DE PÁGINA ---
    doc.setFontSize(9);
    doc.setFont("helvetica", "italic");
    doc.setTextColor(100);
    doc.text("Gracias por su confianza. Guarde este ticket para devoluciones.", 105, 280, { align: 'center' });

    // 2. Guardar PDF
    doc.save(`Ticket_Venta_${idTicket}.pdf`);
  }

  generateInventoryPdf(articulos: any[]): void {
    const doc = new jsPDF('p', 'mm', 'a4');
    const fecha = new Date().toLocaleDateString('es-ES');

    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);
      const logoData = canvas.toDataURL('image/png');

      // --- CABECERA ---
      doc.addImage(logoData, 'PNG', 15, 10, 60, 30);

      doc.setFontSize(18);
      doc.setFont('helvetica', 'bold');
      doc.text('FARMACIA KO2', 195, 20, { align: 'right' });

      doc.setFontSize(12);
      doc.setFont('helvetica', 'normal');
      doc.text('Warehouse Inventory', 195, 28, { align: 'right' });

      doc.setFontSize(10);
      doc.text(`Generated: ${fecha}`, 195, 34, { align: 'right' });

      doc.setDrawColor(200, 200, 200);
      doc.line(15, 45, 195, 45);

      // --- TABLA ---
      const bodyData = articulos.map(a => [
        a.nombre,
        a.categoria,
        a.codigo || '—',
        `${parseFloat(a.precio).toFixed(2)} €`,
        a.cantidad
      ]);

      autoTable(doc, {
        startY: 50,
        head: [['Name', 'Category', 'Prod. Code', 'Price', 'Quantity']],
        body: bodyData,
        theme: 'striped',
        headStyles: { fillColor: [52, 58, 64], textColor: 255 },
        styles: { fontSize: 9, cellPadding: 3 },
        columnStyles: {
          3: { halign: 'right' },
          4: { halign: 'center' }
        }
      });

      // --- FOOTER ---
      doc.setFontSize(9);
      doc.setFont('helvetica', 'italic');
      doc.setTextColor(100);
      doc.text('FARMACIA KO2 — Todos los derechos reservados', 105, 288, { align: 'center' });

      const fechaArchivo = new Date().toISOString().split('T')[0];
      doc.save(`Inventory_${fechaArchivo}.pdf`);
    };

    img.src = 'assets/images/logo.png';
  }
}